code_example:
#include <iostream>
#include <type_traits>

// Generic function enabled only for integral types
template<typename T>
typename std::enable_if<std::is_integral<T>::value, void>::type
printTypeInfo(T value) {
    std::cout << "Integral type with value: " << value << std::endl;
}

// Generic function enabled only for floating-point types
template<typename T>
typename std::enable_if<std::is_floating_point<T>::value, void>::type
printTypeInfo(T value) {
    std::cout << "Floating-point type with value: " << value << std::endl;
}

int main() {
    printTypeInfo(42);        // Calls integral version
    printTypeInfo(3.14);      // Calls floating-point version
    return 0;
}
